import graph; defaultpen(linewidth(0.8));
size(150,IgnoreAspect);
real f(real x)
{

return x*(15-x);
}
xaxis(Arrows(4));
yaxis(ymax=f(7.5),Arrows(4));
draw(graph(f,-3,18),Arrows(4));
label("Area",(0,f(7.5)),N);
label("$l$",(18,0),S);[/asy]

